<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import QuestionConfirmation from '../../components/QuestionConfirmation.vue'
import QuestionRecovery from '../../components/QuestionRecovery.vue'
import {operatorSession,operatorToken} from '../../services/operator-session.js'
import {createKnowledgeApi,createKnowledgeRecovery,validKnowledgeBody,KNOWLEDGE_FIELDS} from '../../services/licensed-knowledge.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {createQuestionConfirmation,pendingQuestion} from '../../services/community-question-recovery.js'
import {imageRequestKey} from '../../services/private-images.js'
const state=reactive(initialDiagnosisState()),form=reactive({title:'',publisher:'',document_version:'',source_reference:'',license_reference:'',model_id:'',valid_from:'',valid_to:'',body:'',license_confirmed:false,search_allowed:false,excerpt_allowed:false,ai_allowed:false,embedding_allowed:false,embedding_policy_version:'KNOWLEDGE_EMBEDDING_V1'}),editing=ref(null),confirmation=reactive({prompt:null}),prompt=ref(null),api=createKnowledgeApi()
const modelPage=ref(1)
const token=operatorToken,allowed=()=>operatorSession.canKnowledge,recovery=createKnowledgeRecovery({actor:()=>operatorSession.actorId,role:()=> 'admin',scope:()=> 'documents'}),gate=createQuestionConfirmation({state:confirmation,preview:()=>prompt.value})
function clear(){editing.value=null;for(const k of KNOWLEDGE_FIELDS)form[k]=['license_confirmed','search_allowed','excerpt_allowed','ai_allowed','embedding_allowed'].includes(k)?false:k==='embedding_policy_version'?'KNOWLEDGE_EMBEDDING_V1':'';prompt.value=null}
const flow=createAsyncDiagnosisFlow({state,token,allowed,scope:()=>`knowledge:${operatorSession.actorId}`,load:async(t,p)=>{const [documents,models]=await Promise.all([api.admin(t,p),api.models(t,modelPage.value)]);return {...documents,models}},write:(t,a,id,b,k)=>api.write(t,a,id,b,k),newKey:imageRequestKey,recovery,confirm:gate.ask,onWritten:clear})
const blocked=()=>state.busy||state.retry||state.kind==='storage'
function chooseModel(e){const row=state.data?.models.items[Number(e.detail.value)];if(row&&!blocked())form.model_id=String(row.model_id)}
function modelLabel(row){return `${row.brand||''} ${row.series||''} ${row.year||''} ${row.config_name||''}`}
let visible=false
function edit(row){if(blocked()||row.status!=='DRAFT'||!state.data?.items.includes(row))return;editing.value={id:row.id,revision:row.revision};Object.assign(form,row.payload,{model_id:String(row.payload.model_id),license_confirmed:false,search_allowed:false,excerpt_allowed:false,ai_allowed:false,embedding_allowed:false,embedding_policy_version:'KNOWLEDGE_EMBEDDING_V1'})}
function save(){if(blocked())return;const b=Object.fromEntries(KNOWLEDGE_FIELDS.map(k=>[k,['license_confirmed','search_allowed','excerpt_allowed','ai_allowed','embedding_allowed'].includes(k)?form[k]:k==='model_id'?Number(form[k]):form[k].trim()]));const action=editing.value?'update':'create';if(editing.value)b.expected_revision=editing.value.revision;if(!validKnowledgeBody(b,action)){state.message='请填写正文、来源、许可凭证、精确车型和UTC有效期；各项用途须明确选择';return}prompt.value={title:'确认保存许可资料草稿',lines:[`资料 ${editing.value?.id||'新建'} · 原版本 ${editing.value?.revision||0}`,b.title,b.publisher,b.document_version,`公开来源：${b.source_reference}`,`内部许可依据：${b.license_reference}`,`车型 ${b.model_id} · ${b.valid_from} 至 ${b.valid_to}`,`许可已确认 ${b.license_confirmed} · 检索 ${b.search_allowed} · 摘录 ${b.excerpt_allowed} · AI ${b.ai_allowed} · 本地私有嵌入 ${b.embedding_allowed} · 策略 ${b.embedding_policy_version}`,b.body]};flow.save(action,editing.value?.id||0,b)}
function status(row,target){if(blocked()||!state.data?.items.includes(row))return;const p=row.payload;prompt.value={title:target==='PUBLISHED'?'确认冻结并发布此资料':'确认停止此资料引用',lines:[`资料 ${row.id} · 版本 ${row.revision}`,p.title,p.publisher,p.document_version,`车型 ${p.model_id} · ${p.valid_from} 至 ${p.valid_to}`,p.source_reference,p.license_reference,`许可确认 ${p.license_confirmed} · 检索 ${p.search_allowed} · 摘录 ${p.excerpt_allowed} · AI ${p.ai_allowed} · 本地私有嵌入 ${p.embedding_allowed===true} · 策略 ${p.embedding_policy_version||'未授权'}`,p.body,target==='PUBLISHED'?'发布后正文冻结；修订须新建独立版本。':'停止后拒绝新读取和AI引用，已复制的文字不能远程删除。']};flow.save('status',row.id,{expected_revision:row.revision,status:target})}
function reset(){gate.cancel();flow.reset();clear()}
watch(()=>[token(),operatorSession.actorId,allowed()],()=>{reset();if(visible&&token()&&allowed())flow.load()},{flush:'sync'})
onShow(()=>{visible=true;if(token()&&allowed())flow.load()});function hide(){visible=false;reset()}onHide(hide);onUnload(hide)
</script>
<template><view class="reservation-page"><text class="reservation-title">授权专业资料管理</text><text>仅录入有明确许可的资料；内部许可凭证不向车主显示。默认不发布、不启用AI或嵌入。嵌入许可不代表索引已生成；当前车主检索仍为关键词。</text><text v-if="!allowed()">需要独立许可资料管理权限</text><button v-if="!token()" @tap="uni.navigateTo({url:'/pages/operator/login'})">运营登录</button><QuestionRecovery :state="state" :flow="flow" :pending="pendingQuestion(recovery)"/><button :disabled="state.busy" @tap="flow.load(state.page)">刷新并核对资料</button><template v-if="allowed()&&state.data"><view class="reservation-panel"><text>{{editing?'修改草稿 '+editing.id:'新建资料版本'}}</text><input v-model="form.title" maxlength="120" :disabled="blocked()" placeholder="资料标题"/><input v-model="form.publisher" maxlength="120" :disabled="blocked()" placeholder="出版者/权利人"/><input v-model="form.document_version" maxlength="80" :disabled="blocked()" placeholder="原资料版本"/><input v-model="form.source_reference" maxlength="500" :disabled="blocked()" placeholder="可向车主展示的来源说明"/><input v-model="form.license_reference" maxlength="500" :disabled="blocked()" placeholder="内部许可凭证说明"/><picker :range="state.data.models.items.map(modelLabel)" :disabled="blocked()" @change="chooseModel"><view>精确车型：{{state.data.models.items.find(r=>String(r.model_id)===form.model_id)?modelLabel(state.data.models.items.find(r=>String(r.model_id)===form.model_id)):(form.model_id?'原车型编号 '+form.model_id:'请选择品牌/车系/年款/配置')}}</view></picker><button v-if="modelPage>1" :disabled="blocked()" @tap="modelPage--;flow.load(state.page)">上一页车型</button><button v-if="modelPage*20<state.data.models.total" :disabled="blocked()" @tap="modelPage++;flow.load(state.page)">下一页车型</button><input v-model="form.valid_from" :disabled="blocked()" placeholder="生效UTC：2026-10-17T00:00:00Z"/><input v-model="form.valid_to" :disabled="blocked()" placeholder="截止UTC：2026-12-31T00:00:00Z"/><textarea v-model="form.body" maxlength="20000" :disabled="blocked()" placeholder="授权资料正文（最多10000字），不填写车主私有信息"/><checkbox-group class="knowledge-permissions" @change="['license_confirmed','search_allowed','excerpt_allowed','ai_allowed','embedding_allowed'].forEach(k=>form[k]=$event.detail.value.includes(k))"><label v-for="entry in [['license_confirmed','已核对合法授权凭证'],['search_allowed','允许检索'],['excerpt_allowed','允许向车主提供摘录'],['ai_allowed','允许将摘录交给AI服务'],['embedding_allowed','单独允许本地私有嵌入索引（不授权外部模型）']]" :key="entry[0]"><checkbox :value="entry[0]" :checked="form[entry[0]]" :disabled="blocked()"/>{{entry[1]}}</label></checkbox-group><button :disabled="blocked()" @tap="save">完整确认并保存草稿</button><button :disabled="blocked()" @tap="clear">清空表单</button></view><view v-for="row in state.data.items" :key="row.id" class="reservation-panel"><text>{{row.payload.title}} · {{row.payload.document_version}} · {{row.status}} · 版本 {{row.revision}}</text><text>车型 {{row.payload.model_id}} · {{row.payload.valid_from}} 至 {{row.payload.valid_to}}</text><button v-if="row.status==='DRAFT'" :disabled="blocked()" @tap="edit(row)">编辑草稿并重新确认许可</button><button v-if="row.status==='DRAFT'" :disabled="blocked()||!row.payload.license_confirmed||!row.payload.search_allowed||!row.payload.excerpt_allowed" @tap="status(row,'PUBLISHED')">预览发布冻结</button><button v-if="row.status==='PUBLISHED'" :disabled="blocked()" @tap="status(row,'STOPPED')">预览停止引用</button><text v-if="row.status==='STOPPED'">原公开引用保持失效；修订请新建资料版本</text></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页</button><button v-if="state.page*20<state.data.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页</button></template><QuestionConfirmation :prompt="confirmation.prompt" @answer="gate.settle"/></view></template>

<style scoped>
.knowledge-permissions{display:flex;flex-direction:column;gap:16rpx}.knowledge-permissions label{display:flex;align-items:flex-start;gap:12rpx;line-height:40rpx}.knowledge-permissions checkbox{flex-shrink:0}
</style>
